<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\FounderInterestRequest;use App\Models\Place;use Illuminate\Contracts\View\View;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class PrelaunchController extends Controller {public function index():View{return view('admin.prelaunch',['requests'=>FounderInterestRequest::latest()->get(),'readiness'=>['legal_identity'=>filled(config('legal.owner_name'))&&filled(config('legal.contact_email')),'social_google'=>filled(config('services.google.client_id')),'social_facebook'=>filled(config('services.facebook.client_id')),'catalog_ready'=>Place::where('is_founder_candidate',true)->whereIn('founder_stage',['ready','published'])->count(),'published_places'=>Place::where('publication_status','published')->count()]]);}public function update(Request $request,FounderInterestRequest $founderRequest):RedirectResponse{$data=$request->validate(['status'=>['required',Rule::in(['new','reviewing','contacted','qualified','declined'])],'admin_notes'=>['nullable','string','max:3000']]);$data['assigned_to']=$request->user()->id;if($data['status']==='contacted'&&!$founderRequest->contacted_at)$data['contacted_at']=now();$founderRequest->update($data);return back()->with('prelaunch_status','Seguimiento actualizado.');}}
